     1→use anyhow::Result;
     2→use clap::Parser;
     3→use std::process::ExitCode;
     4→
     5→use xt::all::{build_all, print_run_summary, print_summary, print_test_summary, run_all, test_all};
     6→use xt::binary::strip_binary;
     7→use xt::cargo_build::build_crate;
     8→use xt::cli::{Cli, Commands, TspecCommands};
     9→use xt::compare::compare_specs;
    10→use xt::find_paths::{find_crate_dir, find_tspecs, find_workspace_root};
    11→use xt::run::run_binary;
    12→use xt::testing::test_crate;
    13→use xt::workspace::WorkspaceInfo;
    14→
    15→fn main() -> ExitCode {
    16→    match run() {
    17→        Ok(code) => code,
    18→        Err(e) => {
    19→            eprintln!("error: {e}");
    20→            ExitCode::from(1)
    21→        }
    22→    }
    23→}
    24→
    25→fn run() -> Result<ExitCode> {
    26→    let cli = Cli::parse();
    27→
    28→    match cli.command {
    29→        Commands::Build {
    30→            crate_name,
    31→            tspec,
    32→            release,
    33→            strip,
    34→            fail_fast,
    35→        } => match crate_name {
    36→            None => {
    37→                // Build all crates
    38→                let workspace = WorkspaceInfo::discover()?;
    39→                let results = build_all(&workspace, tspec.as_deref(), release, strip, fail_fast);
    40→                return Ok(print_summary(&results));
    41→            }
    42→            Some(name) => {
    43→                let result = build_crate(&name, tspec.as_deref(), release)?;
    44→                if strip {
    45→                    strip_binary(&result.binary_path)?;
    46→                }
    47→            }
    48→        },
    49→        Commands::Run {
    50→            crate_name,
    51→            tspec,
    52→            release,
    53→            strip,
    54→        } => match crate_name {
    55→            None => {
    56→                // Run all apps
    57→                let workspace = WorkspaceInfo::discover()?;
    58→                let results = run_all(&workspace, tspec.as_deref(), release, strip);
    59→                return Ok(print_run_summary(&results));
    60→            }
    61→            Some(name) => {
    62→                // Build, optionally strip, then run
    63→                let result = build_crate(&name, tspec.as_deref(), release)?;
    64→                if strip {
    65→                    strip_binary(&result.binary_path)?;
    66→                }
    67→                let exit_code = run_binary(&result.binary_path)?;
    68→                std::process::exit(exit_code);
    69→            }
    70→        },
    71→        Commands::Test {
    72→            crate_name,
    73→            tspec,
    74→            release,
    75→            fail_fast,
    76→        } => match crate_name {
    77→            None => {
    78→                // Test all crates
    79→                let workspace = WorkspaceInfo::discover()?;
    80→                let results = test_all(&workspace, tspec.as_deref(), release, fail_fast);
    81→                return Ok(print_test_summary(&results));
    82→            }
    83→            Some(name) => {
    84→                test_crate(&name, tspec.as_deref(), release)?;
    85→            }
    86→        },
    87→        Commands::Compare {
    88→            crate_name,
    89→            tspec,
    90→            release,
    91→            strip,
    92→        } => {
    93→            let workspace = find_workspace_root()?;
    94→            let crate_dir = find_crate_dir(&workspace, &crate_name)?;
    95→            let spec_paths = find_tspecs(&crate_dir, &tspec)?;
    96→            compare_specs(&crate_name, &spec_paths, release, strip)?;
    97→        }
    98→        Commands::Compat { crate_name, spec } => {
    99→            match spec {
   100→                Some(s) => println!("compat add: crate={crate_name} spec={s}"),
   101→                None => println!("compat show: crate={crate_name}"),
   102→            }
   103→            // TODO: implement
   104→        }
   105→        Commands::Incompat { crate_name, spec } => {
   106→            println!("incompat add: crate={crate_name} spec={spec}");
   107→            // TODO: implement
   108→        }
   109→        Commands::Tspec { command } => match command {
   110→            TspecCommands::List { crate_name } => {
   111→                xt::ts_cmd::list_tspecs(crate_name.as_deref())?;
   112→            }
   113→            TspecCommands::Show { crate_name, tspec } => {
   114→                xt::ts_cmd::show_tspec(&crate_name, tspec.as_deref())?;
   115→            }
   116→            TspecCommands::Hash { crate_name, tspec } => {
   117→                xt::ts_cmd::hash_tspec(&crate_name, tspec.as_deref())?;
   118→            }
   119→            TspecCommands::New {
   120→                crate_name,
   121→                name,
   122→                from,
   123→            } => {
   124→                xt::ts_cmd::new_tspec(&crate_name, &name, from.as_deref())?;
   125→            }
   126→            TspecCommands::Set {
   127→                crate_name,
   128→                assignment,
   129→                tspec,
   130→            } => {
   131→                let (key, value) = assignment.split_once('=').ok_or_else(|| {
   132→                    anyhow::anyhow!("invalid assignment '{}': expected key=value", assignment)
   133→                })?;
   134→                xt::ts_cmd::set_value(&crate_name, key, value, tspec.as_deref())?;
   135→            }
   136→        },
   137→    }
   138→
   139→    Ok(ExitCode::SUCCESS)
   140→}
