     1→//! `cargo xt ts list` - List tspec files
     2→
     3→use anyhow::Result;
     4→use std::path::Path;
     5→
     6→use crate::TSPEC_SUFFIX;
     7→use crate::find_paths::{find_crate_dir, find_workspace_root};
     8→use crate::workspace::WorkspaceInfo;
     9→
    10→/// List all tspec files in workspace or for a specific crate
    11→pub fn list_tspecs(crate_name: Option<&str>) -> Result<()> {
    12→    let workspace = find_workspace_root()?;
    13→
    14→    match crate_name {
    15→        Some(name) => {
    16→            let crate_dir = find_crate_dir(&workspace, name)?;
    17→            let tspecs = find_tspec_files(&crate_dir)?;
    18→            print_crate_tspecs(name, &crate_dir, &tspecs);
    19→        }
    20→        None => {
    21→            let info = WorkspaceInfo::discover()?;
    22→            let mut found_any = false;
    23→
    24→            for member in &info.members {
    25→                let tspecs = find_tspec_files(&member.path)?;
    26→                if !tspecs.is_empty() {
    27→                    print_crate_tspecs(&member.name, &member.path, &tspecs);
    28→                    found_any = true;
    29→                }
    30→            }
    31→
    32→            if !found_any {
    33→                println!("No *{} files found in workspace", TSPEC_SUFFIX);
    34→            }
    35→        }
    36→    }
    37→
    38→    Ok(())
    39→}
    40→
    41→/// Find all tspec files (files ending with TSPEC_SUFFIX) in a directory
    42→pub(crate) fn find_tspec_files(dir: &Path) -> Result<Vec<String>> {
    43→    let mut files = Vec::new();
    44→
    45→    if let Ok(entries) = std::fs::read_dir(dir) {
    46→        for entry in entries.filter_map(|e| e.ok()) {
    47→            let name = entry.file_name().to_string_lossy().to_string();
    48→            if name.ends_with(TSPEC_SUFFIX) {
    49→                files.push(name);
    50→            }
    51→        }
    52→    }
    53→
    54→    files.sort();
    55→    Ok(files)
    56→}
    57→
    58→/// Print tspec files for a crate
    59→fn print_crate_tspecs(crate_name: &str, crate_dir: &Path, tspecs: &[String]) {
    60→    println!("{}:", crate_name);
    61→    for tspec in tspecs {
    62→        let path = crate_dir.join(tspec);
    63→        let size = std::fs::metadata(&path)
    64→            .map(|m| format_size(m.len()))
    65→            .unwrap_or_else(|_| "?".to_string());
    66→        println!("  {} ({})", tspec, size);
    67→    }
    68→}
    69→
    70→/// Format file size in human-readable form
    71→pub(crate) fn format_size(bytes: u64) -> String {
    72→    if bytes < 1024 {
    73→        format!("{} B", bytes)
    74→    } else {
    75→        format!("{:.1} KB", bytes as f64 / 1024.0)
    76→    }
    77→}
