     1→//! `cargo xt ts show` - Show tspec contents
     2→
     3→use anyhow::Result;
     4→use std::path::Path;
     5→
     6→use crate::TSPEC_SUFFIX;
     7→use crate::find_paths::{find_crate_dir, find_tspec, find_workspace_root};
     8→
     9→use super::list::find_tspec_files;
    10→
    11→/// Show a tspec file's contents
    12→pub fn show_tspec(crate_name: &str, tspec: Option<&str>) -> Result<()> {
    13→    let workspace = find_workspace_root()?;
    14→    let crate_dir = find_crate_dir(&workspace, crate_name)?;
    15→
    16→    match tspec {
    17→        Some(name) => {
    18→            // Explicit tspec - show just that one
    19→            let path = find_tspec(&crate_dir, Some(name))?;
    20→            match path {
    21→                Some(p) => print_tspec_content(&p)?,
    22→                None => anyhow::bail!("tspec '{}' not found for crate '{}'", name, crate_name),
    23→            }
    24→        }
    25→        None => {
    26→            // No tspec specified - show all tspec files
    27→            let tspecs = find_tspec_files(&crate_dir)?;
    28→            if tspecs.is_empty() {
    29→                println!("No *{} files found for {}", TSPEC_SUFFIX, crate_name);
    30→            } else {
    31→                for (i, name) in tspecs.iter().enumerate() {
    32→                    if i > 0 {
    33→                        println!();
    34→                    }
    35→                    print_tspec_content(&crate_dir.join(name))?;
    36→                }
    37→            }
    38→        }
    39→    }
    40→
    41→    Ok(())
    42→}
    43→
    44→/// Print a single tspec file with header
    45→fn print_tspec_content(path: &Path) -> Result<()> {
    46→    let filename = path
    47→        .file_name()
    48→        .map(|s| s.to_string_lossy())
    49→        .unwrap_or_default();
    50→    println!("====== {} ======", filename);
    51→    let content = std::fs::read_to_string(path)?;
    52→    print!("{}", content);
    53→    if !content.ends_with('\n') {
    54→        println!();
    55→    }
    56→    Ok(())
    57→}
    58→

