     1→//! `cargo xt ts hash` - Show tspec content hash
     2→
     3→use anyhow::Result;
     4→use std::path::Path;
     5→
     6→use crate::TSPEC_SUFFIX;
     7→use crate::find_paths::{find_crate_dir, find_tspec, find_workspace_root};
     8→use crate::tspec::{hash_spec, load_spec};
     9→
    10→use super::list::find_tspec_files;
    11→
    12→/// Show hash of a tspec file
    13→pub fn hash_tspec(crate_name: &str, tspec: Option<&str>) -> Result<()> {
    14→    let workspace = find_workspace_root()?;
    15→    let crate_dir = find_crate_dir(&workspace, crate_name)?;
    16→
    17→    match tspec {
    18→        Some(name) => {
    19→            // Explicit tspec - hash just that one
    20→            let path = find_tspec(&crate_dir, Some(name))?;
    21→            match path {
    22→                Some(p) => print_tspec_hash(&p)?,
    23→                None => anyhow::bail!("tspec '{}' not found for crate '{}'", name, crate_name),
    24→            }
    25→        }
    26→        None => {
    27→            // No tspec specified - hash all tspec files
    28→            let tspecs = find_tspec_files(&crate_dir)?;
    29→            if tspecs.is_empty() {
    30→                println!("No *{} files found for {}", TSPEC_SUFFIX, crate_name);
    31→            } else {
    32→                for name in &tspecs {
    33→                    print_tspec_hash(&crate_dir.join(name))?;
    34→                }
    35→            }
    36→        }
    37→    }
    38→
    39→    Ok(())
    40→}
    41→
    42→/// Print hash of a single tspec file
    43→fn print_tspec_hash(path: &Path) -> Result<()> {
    44→    let filename = path
    45→        .file_name()
    46→        .map(|s| s.to_string_lossy())
    47→        .unwrap_or_default();
    48→    let spec = load_spec(path)?;
    49→    let hash = hash_spec(&spec)?;
    50→    println!("{}: {}", filename, hash);
    51→    Ok(())
    52→}
