     1→//! `cargo xt ts new` - Create a new tspec file
     2→
     3→use anyhow::Result;
     4→use std::path::Path;
     5→
     6→use crate::TSPEC_SUFFIX;
     7→use crate::find_paths::{find_crate_dir, find_tspec, find_workspace_root};
     8→use crate::tspec::{load_spec, save_spec};
     9→use crate::types::Spec;
    10→
    11→/// Create a new tspec file (public entry point)
    12→pub fn new_tspec(crate_name: &str, name: &str, from: Option<&str>) -> Result<()> {
    13→    let workspace = find_workspace_root()?;
    14→    let crate_dir = find_crate_dir(&workspace, crate_name)?;
    15→
    16→    // Resolve source spec if --from provided
    17→    let source_spec = match from {
    18→        Some(source) => {
    19→            let source_path = resolve_source_spec(&workspace, crate_name, source)?;
    20→            Some(load_spec(&source_path)?)
    21→        }
    22→        None => None,
    23→    };
    24→
    25→    create_tspec_file(&workspace, &crate_dir, name, source_spec.as_ref())
    26→}
    27→
    28→/// Resolve the source spec path from a --from argument
    29→fn resolve_source_spec(
    30→    workspace: &Path,
    31→    crate_name: &str,
    32→    source: &str,
    33→) -> Result<std::path::PathBuf> {
    34→    // Parse source: could be "crate/spec" or just "spec"
    35→    let (source_crate, source_spec) = if source.contains('/') {
    36→        let parts: Vec<&str> = source.splitn(2, '/').collect();
    37→        (parts[0], Some(parts[1]))
    38→    } else {
    39→        // Same crate, just spec name
    40→        (crate_name, Some(source))
    41→    };
    42→
    43→    let source_crate_dir = find_crate_dir(workspace, source_crate)?;
    44→    find_tspec(&source_crate_dir, source_spec)?.ok_or_else(|| {
    45→        anyhow::anyhow!(
    46→            "source tspec '{}' not found in crate '{}'",
    47→            source_spec.unwrap_or("tspec"),
    48→            source_crate
    49→        )
    50→    })
    51→}
    52→
    53→/// Create a tspec file - core logic, testable
    54→fn create_tspec_file(
    55→    workspace: &Path,
    56→    crate_dir: &Path,
    57→    name: &str,
    58→    source_spec: Option<&Spec>,
    59→) -> Result<()> {
    60→    let spec = source_spec.cloned().unwrap_or_default();
    61→    let output_path = crate_dir.join(format!("{}{}", name, TSPEC_SUFFIX));
    62→
    63→    // Check if file already exists
    64→    if output_path.exists() {
    65→        anyhow::bail!(
    66→            "tspec '{}' already exists. Use a different name or delete the existing file.",
    67→            output_path.file_name().unwrap().to_string_lossy(),
    68→        );
    69→    }
    70→
    71→    // Save the spec
    72→    save_spec(&spec, &output_path)?;
    73→
    74→    println!(
    75→        "Created {}",
    76→        output_path
    77→            .strip_prefix(workspace)
    78→            .unwrap_or(&output_path)
    79→            .display()
    80→    );
    81→
    82→    Ok(())
    83→}
    84→
