    10→/// Set a value in a tspec and save as versioned snapshot
    11→pub fn set_value(crate_name: &str, key: &str, value: &str, tspec: Option<&str>) -> Result<()> {
    12→    let workspace = find_workspace_root()?;
    13→    let crate_dir = find_crate_dir(&workspace, crate_name)?;
    14→
    15→    // Load existing spec or use default
    16→    let mut spec = match find_tspec(&crate_dir, tspec)? {
    17→        Some(path) => load_spec(&path)?,
    18→        None => Spec::default(),
    19→    };
    20→
    21→    // Apply the key=value change
    22→    apply_value(&mut spec, key, value)?;
    23→
    24→    // Determine base name for snapshot
    25→    let base_name = match tspec {
    26→        Some(t) => {
    27→            // Strip suffix if present
    28→            t.strip_suffix(crate::TSPEC_SUFFIX)
    29→                .or_else(|| t.strip_suffix(".toml"))
    30→                .unwrap_or(t)
    31→                .to_string()
    32→        }
    33→        None => "tspec".to_string(),
    34→    };
    35→
    36→    // Save as versioned snapshot
    37→    let output_path = save_spec_snapshot(&spec, &base_name, &crate_dir)?;
    38→
    39→    println!(
    40→        "Saved {}",
    41→        output_path
    42→            .strip_prefix(&workspace)
    43→            .unwrap_or(&output_path)
    44→            .display()
    45→    );
    46→
    47→    Ok(())
    48→}
    49→
    50→/// Apply key=value to a spec
    51→fn apply_value(spec: &mut Spec, key: &str, value: &str) -> Result<()> {
    52→    match key {
    53→        // Top-level high-level options
    54→        "panic" => {
    55→            spec.panic = Some(parse_panic_mode(value)?);
    56→        }
    57→        "strip" => {
    58→            spec.strip = Some(parse_strip_mode(value)?);
    59→        }
    60→
    61→        // Cargo config
    62→        "cargo.profile" => {
    63→            spec.cargo.profile = Some(parse_profile(value)?);
    64→        }
    65→        "cargo.target_triple" => {
    66→            spec.cargo.target_triple = Some(value.to_string());
    67→        }
    68→
    69→        // Rustc config
    70→        "rustc.opt_level" => {
    71→            spec.rustc.opt_level = Some(parse_opt_level(value)?);
    72→        }
    73→        "rustc.panic" => {
    74→            spec.rustc.panic = Some(parse_panic_strategy(value)?);
    75→        }
    76→        "rustc.lto" => {
    77→            spec.rustc.lto = Some(parse_bool(value)?);
    78→        }
    79→        "rustc.codegen_units" => {
    80→            spec.rustc.codegen_units = Some(
    81→                value
    82→                    .parse()
    83→                    .with_context(|| format!("invalid codegen_units: {}", value))?,
    84→            );
    85→        }
    86→
    87→        _ => bail!("unknown key: {}", key),
    88→    }
    89→
    90→    Ok(())
    91→}
    92→
    93→fn parse_panic_mode(s: &str) -> Result<PanicMode> {
    94→    match s {
    95→        "unwind" => Ok(PanicMode::Unwind),
    96→        "abort" => Ok(PanicMode::Abort),
    97→        "immediate-abort" => Ok(PanicMode::ImmediateAbort),
    98→        _ => bail!(
    99→            "invalid panic mode: {} (expected: unwind, abort, immediate-abort)",
   100→            s
   101→        ),
   102→    }
   103→}
   104→
   105→fn parse_strip_mode(s: &str) -> Result<StripMode> {
   106→    match s {
   107→        "none" => Ok(StripMode::None),
   108→        "debuginfo" => Ok(StripMode::Debuginfo),
   109→        "symbols" => Ok(StripMode::Symbols),
   110→        _ => bail!(
   111→            "invalid strip mode: {} (expected: none, debuginfo, symbols)",
   112→            s
   113→        ),
   114→    }
   115→}
   116→
   117→fn parse_profile(s: &str) -> Result<Profile> {
   118→    match s {
   119→        "debug" => Ok(Profile::Debug),
   120→        "release" => Ok(Profile::Release),
   121→        _ => bail!("invalid profile: {} (expected: debug, release)", s),
   122→    }
   123→}
   124→
   125→fn parse_opt_level(s: &str) -> Result<OptLevel> {
   126→    match s {
   127→        "0" => Ok(OptLevel::O0),
   128→        "1" => Ok(OptLevel::O1),
   129→        "2" => Ok(OptLevel::O2),
   130→        "3" => Ok(OptLevel::O3),
   131→        "s" => Ok(OptLevel::Os),
   132→        "z" => Ok(OptLevel::Oz),
   133→        _ => bail!("invalid opt-level: {} (expected: 0, 1, 2, 3, s, z)", s),
   134→    }
   135→}
   136→
   137→fn parse_panic_strategy(s: &str) -> Result<PanicStrategy> {
   138→    match s {
   139→        "abort" => Ok(PanicStrategy::Abort),
   140→        "unwind" => Ok(PanicStrategy::Unwind),
   141→        "immediate-abort" => Ok(PanicStrategy::ImmediateAbort),
   142→        _ => bail!(
   143→            "invalid panic strategy: {} (expected: abort, unwind, immediate-abort)",
   144→            s
   145→        ),
   146→    }
   147→}
   148→
   149→fn parse_bool(s: &str) -> Result<bool> {
   150→    match s {
   151→        "true" | "yes" | "1" => Ok(true),
   152→        "false" | "no" | "0" => Ok(false),
   153→        _ => bail!("invalid boolean: {} (expected: true/false)", s),
   154→    }
   155→}
