     8→/// Extract crate name from Cargo.toml
     9→pub fn get_crate_name(crate_dir: &Path) -> Result<String> {
    10→    let cargo_toml = crate_dir.join("Cargo.toml");
    11→    let content = std::fs::read_to_string(&cargo_toml)
    12→        .with_context(|| format!("failed to read {}", cargo_toml.display()))?;
    13→
    14→    // Simple parsing - look for name = "..." in [package] section
    15→    let mut in_package = false;
    16→    for line in content.lines() {
    17→        let line = line.trim();
    18→        if line == "[package]" {
    19→            in_package = true;
    20→            continue;
    21→        }
    22→        if line.starts_with('[') {
    23→            in_package = false;
    24→            continue;
    25→        }
    26→        if in_package
    27→            && line.starts_with("name")
    28→            && let Some(eq_pos) = line.find('=')
    29→        {
    30→            let value = line[eq_pos + 1..].trim();
    31→            let value = value.trim_matches('"').trim_matches('\'');
    32→            return Ok(value.to_string());
    33→        }
    34→    }
    35→    bail!("could not find package name in {}", cargo_toml.display());
    36→}
    37→
    38→/// Find the workspace root by looking for Cargo.toml with [workspace]
    39→pub fn find_workspace_root() -> Result<PathBuf> {
    40→    let mut dir = std::env::current_dir()?;
    41→    loop {
    42→        let cargo_toml = dir.join("Cargo.toml");
    43→        if cargo_toml.exists() {
    44→            let content = std::fs::read_to_string(&cargo_toml)?;
    45→            if content.contains("[workspace]") {
    46→                return Ok(dir);
    47→            }
    48→        }
    49→        if !dir.pop() {
    50→            bail!("could not find workspace root");
    51→        }
    52→    }
    53→}
    54→
    55→/// Find a crate's directory - tries as path first, then searches standard locations
    56→pub fn find_crate_dir(workspace: &Path, name: &str) -> Result<PathBuf> {
    57→    // Try as path first (relative or absolute)
    58→    let as_path = PathBuf::from(name);
    59→    if as_path.join("Cargo.toml").exists() {
    60→        return Ok(as_path.canonicalize().unwrap_or(as_path));
    61→    }
    62→
    63→    // Fallback: search libs/, apps/, tools/
    64→    for prefix in ["libs", "apps", "tools"] {
    65→        let path = workspace.join(prefix).join(name);
    66→        if path.join("Cargo.toml").exists() {
    67→            return Ok(path);
    68→        }
    69→    }
    70→
    71→    // Special case: nested test crates like libs/rlibc-x2/tests
    72→    for prefix in ["libs", "apps"] {
    73→        for entry in std::fs::read_dir(workspace.join(prefix))
    74→            .into_iter()
    75→            .flatten()
    76→            .flatten()
    77→        {
    78→            let nested = entry.path().join("tests");
    79→            if nested.join("Cargo.toml").exists()
    80→                && let Ok(pkg_name) = get_crate_name(&nested)
    81→                && pkg_name == name
    82→            {
    83→                return Ok(nested);
    84→            }
    85→        }
    86→    }
    87→
    88→    bail!("crate '{}' not found", name);
    89→}
