    91→/// Find the tspec for a crate - tries as path first, then relative to crate_dir
    92→/// Returns None if no tspec exists (plain cargo build will be used)
    93→pub fn find_tspec(crate_dir: &Path, explicit: Option<&str>) -> Result<Option<PathBuf>> {
    94→    match explicit {
    95→        Some(name) => {
    96→            // Try as path first (relative to cwd or absolute)
    97→            let as_path = PathBuf::from(name);
    98→            if as_path.exists() {
    99→                return Ok(Some(as_path.canonicalize().unwrap_or(as_path)));
   100→            }
   101→
   102→            // Fallback: relative to crate directory
   103→            let in_crate = crate_dir.join(name);
   104→            if in_crate.exists() {
   105→                return Ok(Some(in_crate));
   106→            }
   107→
   108→            // Try with TSPEC_SUFFIX if name has no extension
   109→            if !name.contains('.') {
   110→                let with_suffix = crate_dir.join(format!("{}{}", name, TSPEC_SUFFIX));
   111→                if with_suffix.exists() {
   112→                    return Ok(Some(with_suffix));
   113→                }
   114→            }
   115→
   116→            bail!("tspec not found: {}", name);
   117→        }
   118→        None => {
   119→            let default = crate_dir.join(format!("tspec{}", TSPEC_SUFFIX));
   120→            if default.exists() {
   121→                Ok(Some(default))
   122→            } else {
   123→                Ok(None) // No tspec = plain cargo build
   124→            }
   125→        }
   126→    }
   127→}
