   129→/// Find multiple tspecs by glob patterns
   130→/// If no patterns given, defaults to "tspec*{TSPEC_SUFFIX}"
   131→/// Returns sorted list of paths, errors if none found
   132→pub fn find_tspecs(crate_dir: &Path, patterns: &[String]) -> Result<Vec<PathBuf>> {
   133→    let default_pattern = format!("tspec*{}", TSPEC_SUFFIX);
   134→    let patterns: Vec<&str> = if patterns.is_empty() {
   135→        vec![&default_pattern]
   136→    } else {
   137→        patterns.iter().map(|s| s.as_str()).collect()
   138→    };
   139→
   140→    let mut results = Vec::new();
   141→
   142→    for pattern in &patterns {
   143→        // Try as literal path first (relative to cwd or absolute)
   144→        let as_path = PathBuf::from(pattern);
   145→        if as_path.exists() && as_path.is_file() {
   146→            results.push(as_path.canonicalize().unwrap_or(as_path));
   147→            continue;
   148→        }
   149→
   150→        // Try as literal path relative to crate_dir
   151→        let in_crate = crate_dir.join(pattern);
   152→        if in_crate.exists() && in_crate.is_file() {
   153→            results.push(in_crate);
   154→            continue;
   155→        }
   156→
   157→        // Try as glob pattern in crate_dir
   158→        let glob_pattern =
   159→            Pattern::new(pattern).with_context(|| format!("invalid glob pattern: {}", pattern))?;
   160→
   161→        let entries: Vec<_> = std::fs::read_dir(crate_dir)
   162→            .with_context(|| format!("cannot read directory: {}", crate_dir.display()))?
   163→            .filter_map(|e| e.ok())
   164→            .filter(|e| {
   165→                let name = e.file_name().to_string_lossy().to_string();
   166→                e.path().is_file() && glob_pattern.matches(&name)
   167→            })
   168→            .map(|e| e.path())
   169→            .collect();
   170→
   171→        results.extend(entries);
   172→    }
   173→
   174→    // Remove duplicates and sort
   175→    results.sort();
   176→    results.dedup();
   177→
   178→    if results.is_empty() {
   179→        let pattern_list = patterns.join(", ");
   180→        bail!(
   181→            "no tspec files found matching '{}' in {}",
   182→            pattern_list,
   183→            crate_dir.display()
   184→        );
   185→    }
   186→
   187→    Ok(results)
   188→}
