   190→/// Get binary path for a build with a spec
   191→pub fn get_binary_path(workspace: &Path, crate_name: &str, spec: &Spec, release: bool) -> PathBuf {
   192→    let is_release = release || spec.cargo.profile.as_ref() == Some(&Profile::Release);
   193→
   194→    let target = spec.cargo.target_triple.clone().or_else(|| {
   195→        spec.cargo
   196→            .target_json
   197→            .as_ref()
   198→            .and_then(|p| p.file_stem().map(|s| s.to_string_lossy().to_string()))
   199→    });
   200→
   201→    let profile_dir = if is_release { "release" } else { "debug" };
   202→
   203→    match target {
   204→        Some(t) => workspace
   205→            .join("target")
   206→            .join(t)
   207→            .join(profile_dir)
   208→            .join(crate_name),
   209→        None => workspace.join("target").join(profile_dir).join(crate_name),
   210→    }
   211→}
   212→
   213→/// Get binary path for a simple build (no spec)
   214→pub fn get_binary_path_simple(workspace: &Path, crate_name: &str, release: bool) -> PathBuf {
   215→    let profile_dir = if release { "release" } else { "debug" };
   216→    workspace.join("target").join(profile_dir).join(crate_name)
   217→}
